def compute(vars):
    fiscal_2009 = vars["v1"]
    total_incentives = vars["v2"]

    if total_incentives == 0:
        return None

    value = fiscal_2009 / total_incentives
    return {
        "value": value,
        "trace": {
            "fiscal_2009_incentives": fiscal_2009,
            "total_incentives": total_incentives,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
